      settings: {
        effect: "slide",
        coverflow: {
          rotate: { number: 50 },
          depth: { number: 100 },
          stretch: { number: 0 }
        },
        speed: { number: 1000 },
        autoplay_settings: {
          speed: { number: 3000 }
        },
        advanced: {
          between_slides: 0,
          slides_per_view: 1,
          slides_per_group: 1,
          initial_slide: 0
        },
        direction: "horizontal"
      },
      pagination: {
        type: "bullets"
      }
    });

